// Local image preparation uses data URLs permitted by the site's CSP.
window.OwaysImages={async prepare(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('اختر صورة JPG أو PNG أو WebP.');if(file.size>8*1024*1024)throw Error('حجم الصورة يتجاوز 8 ميغابايت.');const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تعذر قراءة الصورة. اختر الملف مجددًا.'));reader.readAsDataURL(file)});const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('تعذر فتح الصورة. تأكد من سلامة الملف وصيغته.'));image.src=source});const width=image.naturalWidth,height=image.naturalHeight;if(!width||!height||width*height>40000000)throw Error('أبعاد الصورة كبيرة جدًا أو غير صالحة.');const canvas=document.createElement('canvas');canvas.width=960;canvas.height=600;const ctx=canvas.getContext('2d');if(!ctx)throw Error('متصفحك لا يدعم تجهيز الصور.');ctx.fillStyle='#edf2f7';ctx.fillRect(0,0,960,600);const scale=Math.min(960/width,600/height),w=width*scale,h=height*scale;ctx.drawImage(image,(960-w)/2,(600-h)/2,w,h);for(const quality of [.84,.74,.64,.54,.44]){const data=canvas.toDataURL('image/jpeg',quality);if(data.startsWith('data:image/jpeg;base64,')&&data.length<=360000)return data}throw Error('تعذر ضغط الصورة للحجم المطلوب. اختر صورة أخرى.')}};
